// Independent fixture composition and first-match oracle; these IDs need no aliases/normalization.
function fixtureRows(blob, defaults) {
  if (Array.isArray(blob)) return blob;
  const rows = defaults.filter(r => !blob.removed.includes(r.pat))
    .map(r => blob.edited.find(e => e.pat === r.pat) || r);
  for (const r of blob.added) {
    const at = rows.findIndex(x => x.pat === r.after);
    rows.splice(r.after === null ? 0 : at >= 0 ? at + 1 : rows.length - 1, 0, r);
  }
  return rows;
}
async function explainedPrices(page, blob, defaults) {
  const s = await state(page), before = fixtureRows(blob, defaults);
  const winner = (rows, id) => rows.find(r => new RegExp(r.pat, 'i').test(id));
  const expected = NOTICE_IDS.map(id => winner(defaults, id));
  const changed = NOTICE_IDS.map((id, i) => [id, winner(before, id), expected[i]])
    .filter(([, a, b]) => a.in !== b.in || a.out !== b.out);
  const lists = [['changed', 'Changed rows'], ['added', 'Newly active rows'],
    ['kept', 'Kept custom rules'], ['outdated', 'Outdated built-in rules removed']];
  const disclosed = lists.flatMap(([key, title]) => {
    const entries = s.fix?.[key] || [];
    if (!entries.length) return [];
    const text = title + ' (' + entries.length + '): ' + entries.slice(0, 5).join('; ') +
      (entries.length > 5 ? '; and ' + (entries.length - 5) + ' more' : '') + '.';
    return s.text.includes(text) ? entries : [];
  });
  const missing = changed.filter(([, a, b]) => !disclosed.some(t =>
    [a.label, b.label].some(label => t === label || t.startsWith(label + ': ')))).map(([id]) => id);
  const actual = await page.evaluate(ids => ids.map(id => {
    const r = Pricing.resolve(id); return [r.in, r.out];
  }), NOTICE_IDS);
  return { pass: s.undo && changed.length > 0 && !missing.length &&
    JSON.stringify(actual) === JSON.stringify(expected.map(r => [r.in, r.out])), missing, changed: changed.length };
}

